/**
 * Converts a JSON Schema (as sent by Anthropic / OpenAI clients) into the
 * OpenAPI subset Gemini accepts in `functionDeclarations[].parameters`.
 *
 * Gemini's `parameters` is a `Schema` proto, not JSON Schema: any key outside
 * that proto is a hard 400 ("Invalid JSON payload received. Unknown name
 * "$schema" at 'tools[0].function_declarations[0].parameters'"). Claude Code's
 * tools are generated by zod's JSON Schema output and carry `$schema`,
 * `additionalProperties`, `exclusiveMinimum`, `const`, `allOf`, `format: uri`
 * and friends, so translated requests need this pass. Runs recursively over
 * properties, items and anyOf, resolving local `$ref`s against `$defs`.
 */

const ALLOWED_KEYS = new Set([
  'type',
  'format',
  'title',
  'description',
  'nullable',
  'enum',
  'items',
  'properties',
  'required',
  'minItems',
  'maxItems',
  'minProperties',
  'maxProperties',
  'minLength',
  'maxLength',
  'pattern',
  'minimum',
  'maximum',
  'anyOf',
  'propertyOrdering',
  'example',
  'default',
]);

// Gemini rejects any other `format` value ("only 'enum' and 'date-time' are
// supported for STRING type").
const ALLOWED_FORMATS: Record<string, Set<string>> = {
  string: new Set(['enum', 'date-time']),
  integer: new Set(['int32', 'int64']),
  number: new Set(['float', 'double']),
};

const MAX_REF_DEPTH = 16;

type Json = Record<string, any>;

function isObject(v: unknown): v is Json {
  return typeof v === 'object' && v !== null && !Array.isArray(v);
}

function resolveRef(ref: string, root: Json): Json | undefined {
  if (!ref.startsWith('#/')) return undefined;
  let node: any = root;
  for (const raw of ref.slice(2).split('/')) {
    const seg = raw.replace(/~1/g, '/').replace(/~0/g, '~');
    if (!isObject(node) || !(seg in node)) return undefined;
    node = node[seg];
  }
  return isObject(node) ? node : undefined;
}

/** Folds `allOf` members into the parent so Gemini sees a single schema. */
function mergeAllOf(schema: Json): Json {
  const { allOf, ...rest } = schema;
  if (!Array.isArray(allOf)) return schema;
  const merged: Json = { ...rest };
  for (const member of allOf) {
    if (!isObject(member)) continue;
    for (const [k, v] of Object.entries(member)) {
      if (k === 'properties' && isObject(v)) {
        merged.properties = { ...(merged.properties ?? {}), ...v };
      } else if (k === 'required' && Array.isArray(v)) {
        merged.required = [...new Set([...(merged.required ?? []), ...v])];
      } else if (!(k in merged)) {
        // First constraint wins; Gemini has no way to express conjunctions.
        merged[k] = v;
      }
    }
  }
  return merged;
}

function sanitize(input: unknown, root: Json, refDepth: number): Json {
  if (!isObject(input)) return {};

  let schema: Json = input;
  if (typeof schema.$ref === 'string') {
    const target = refDepth < MAX_REF_DEPTH ? resolveRef(schema.$ref, root) : undefined;
    const { $ref, ...siblings } = schema;
    // Recursive or unresolvable refs collapse to an untyped object.
    schema = target ? { ...target, ...siblings } : { type: 'object', ...siblings };
    refDepth += 1;
  }
  schema = mergeAllOf(schema);

  const out: Json = {};

  // `type: ["string", "null"]` → `type: "string", nullable: true`.
  let type = schema.type;
  if (Array.isArray(type)) {
    const nonNull = type.filter((t) => t !== 'null');
    if (nonNull.length !== type.length) out.nullable = true;
    if (nonNull.length === 1) {
      type = nonNull[0];
    } else if (nonNull.length > 1) {
      out.anyOf = nonNull.map((t) => sanitize({ ...schema, type: t }, root, refDepth));
      type = undefined;
    } else {
      type = undefined;
    }
  } else if (type === 'null') {
    out.nullable = true;
    type = undefined;
  }
  if (typeof type === 'string') out.type = type;

  for (const [key, value] of Object.entries(schema)) {
    if (key === 'type' || (key === 'anyOf' && out.anyOf)) continue;
    if (!ALLOWED_KEYS.has(key)) continue;

    switch (key) {
      case 'properties':
        if (isObject(value)) {
          out.properties = Object.fromEntries(
            Object.entries(value).map(([name, sub]) => [name, sanitize(sub, root, refDepth)])
          );
        }
        break;
      case 'items':
        // Tuple-form `items: [...]` has no Gemini equivalent; keep the first.
        out.items = sanitize(Array.isArray(value) ? value[0] : value, root, refDepth);
        break;
      case 'anyOf': {
        if (!Array.isArray(value)) break;
        const branches = value.filter(
          (b) => !(isObject(b) && b.type === 'null' && Object.keys(b).length === 1)
        );
        if (branches.length !== value.length) out.nullable = true;
        if (branches.length === 1) {
          Object.assign(out, sanitize(branches[0], root, refDepth), {
            ...(out.nullable ? { nullable: true } : {}),
          });
        } else if (branches.length > 1) {
          out.anyOf = branches.map((b) => sanitize(b, root, refDepth));
        }
        break;
      }
      case 'enum':
        // Gemini enums are string-only.
        if (Array.isArray(value) && value.length > 0 && value.every((v) => typeof v === 'string')) {
          out.enum = value;
        }
        break;
      case 'required':
        if (Array.isArray(value)) out.required = value.filter((v) => typeof v === 'string');
        break;
      case 'format': {
        const allowed = typeof out.type === 'string' && ALLOWED_FORMATS[out.type.toLowerCase()];
        if (allowed && allowed.has(value)) out.format = value;
        break;
      }
      default:
        out[key] = value;
    }
  }

  if (out.anyOf === undefined && Array.isArray(schema.oneOf)) {
    out.anyOf = schema.oneOf.map((b: unknown) => sanitize(b, root, refDepth));
  }

  if (schema.const !== undefined && out.enum === undefined && typeof schema.const === 'string') {
    out.enum = [schema.const];
    out.type ??= 'string';
  }

  // Draft 2020-12 numeric exclusive bounds → closest inclusive bound.
  if (typeof schema.exclusiveMinimum === 'number' && out.minimum === undefined) {
    out.minimum = schema.exclusiveMinimum;
  }
  if (typeof schema.exclusiveMaximum === 'number' && out.maximum === undefined) {
    out.maximum = schema.exclusiveMaximum;
  }

  if (Array.isArray(out.required) && isObject(out.properties)) {
    const names = new Set(Object.keys(out.properties));
    out.required = out.required.filter((r: string) => names.has(r));
  }
  if (Array.isArray(out.required) && out.required.length === 0) delete out.required;

  return out;
}

export function sanitizeGeminiFunctionParameters(schema: unknown): Json {
  const root = isObject(schema) ? schema : {};
  return sanitize(root, root, 0);
}
